package com.bananalab.lite;
import android.content.*;import java.io.*;import java.util.*;import java.lang.reflect.*;import org.json.*;
/** Atomic replacement registry; full workspace bytecode is never loaded. */
final class ProjectRuntime{
 static final class Snapshot{Method jump,sway,chat,celebration,planner;JSONObject plannerData;}
 static volatile Snapshot active=new Snapshot();static volatile String error="";
 static SharedPreferences prefs(Context c){return c.getSharedPreferences("banana-project-runtime",0);}
 static String workspace(Context c)throws Exception{return JavaMethodEditor.hash(JavaProject.working(c).toString()+JavaProject.fingerprint(c));}
 static String digest(File f)throws Exception{try(InputStream in=new FileInputStream(f)){java.security.MessageDigest md=java.security.MessageDigest.getInstance("SHA-256");byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)md.update(b,0,n);StringBuilder out=new StringBuilder();for(byte x:md.digest())out.append(Integer.toHexString((x&255)|256).substring(1));return out.toString();}}
 static File verify(Context c,JSONObject row)throws Exception{JSONObject spec=row.getJSONObject("spec");String canonical=new JSONObject(ProjectReplacementSpec.sources(c,spec)).toString();if(!row.getString("sourceHash").equals(JavaMethodEditor.hash(canonical)))throw new IOException("Cambió el contrato o la fuente del módulo.");File jar=new File(row.getString("jar"));if(!jar.getCanonicalPath().startsWith(OnDeviceJava.home(c).getCanonicalPath()+File.separator)||!jar.isFile()||jar.canWrite()||!digest(jar).equals(row.getString("jarHash")))throw new IOException("El módulo guardado cambió.");return jar;}
 static Snapshot load(Context c,JSONObject modules,boolean trial)throws Exception{Snapshot next=new Snapshot();for(String kind:new String[]{"animacion","chat","acciones","planificador"})if(modules.has(kind)){JSONObject row=modules.getJSONObject(kind),spec=row.getJSONObject("spec");if(!kind.equals(spec.getString("kind")))throw new IOException("Módulo en un destino incorrecto.");File jar=verify(c,row);if(trial)JavaTrial.request(c,jar,spec.toString(),"project",ProjectReplacementSpec.samples(spec));ProjectReplacementSpec.check(c,jar,spec);Class<?> type=ProjectReplacementSpec.type(c,jar,spec);if(kind.equals("animacion")){next.jump=type.getMethod("jump",float.class);next.sway=type.getMethod("sway",float.class);}else if(kind.equals("chat"))next.chat=type.getMethod("socialReply",String.class);else if(kind.equals("planificador")){next.planner=type.getMethod("plan",String.class,float[].class);next.plannerData=PlannerContract.read(spec.getString("body"));}else next.celebration=type.getMethod("celebration");}return next;}
 static synchronized void restore(Context c){try{active=load(c,new JSONObject(prefs(c).getString("active","{}")),false);error="";}catch(Throwable e){active=new Snapshot();error="No cargué las sustituciones: "+AndroidRepair.summary(e);}}
 static synchronized String prepare(Context c,String kind)throws Exception{String hash=workspace(c),prior=prefs(c).getString("active","{}");int rev=prefs(c).getInt("revision",0);JSONObject spec=ProjectReplacementSpec.extract(c,kind);if(!hash.equals(JavaProject.prefs(c).getString("compiledHash",""))){String report=JavaProject.compile(c);if(!hash.equals(JavaProject.prefs(c).getString("compiledHash","")))throw new IOException(report);}Map<String,String> sources=ProjectReplacementSpec.sources(c,spec);OnDeviceJava.Build build=OnDeviceJava.compileSources(c,sources);android.os.Bundle proof=JavaTrial.request(c,build.jar,spec.toString(),"project",ProjectReplacementSpec.samples(spec));JSONObject modules=new JSONObject(prior);JSONObject row=new JSONObject().put("spec",spec).put("jar",build.jar.getAbsolutePath()).put("jarHash",digest(build.jar)).put("sourceHash",JavaMethodEditor.hash(new JSONObject(sources).toString())).put("workspaceHash",hash).put("tests",proof.getInt("samples")).put("pid",proof.getInt("pid"));modules.put(kind,row);JSONObject draft=new JSONObject().put("modules",modules).put("base",rev).put("priorHash",JavaMethodEditor.hash(prior)).put("workspaceHash",hash).put("kind",kind);if(!hash.equals(workspace(c))||rev!=prefs(c).getInt("revision",0)||!prior.equals(prefs(c).getString("active","{}")))throw new IOException("Los cambios quedaron desactualizados durante la prueba.");if(!prefs(c).edit().putString("draft",draft.toString()).commit())throw new IOException("No pude guardar el candidato.");return "Sustitución de "+kind+" preparada: proyecto completo compilado y "+proof.getInt("samples")+" pruebas en otro proceso.\nTodavía no está activa. Decí ‘ver sustitucion java’ y ‘aplica sustitucion java’.";}
 static JSONArray archive(Context c)throws Exception{JSONArray old=new JSONArray(prefs(c).getString("history","[]")),next=new JSONArray();for(int i=Math.max(0,old.length()-7);i<old.length();i++)next.put(old.getJSONObject(i));next.put(new JSONObject(prefs(c).getString("active","{}")));return next;}
 static void commit(Context c,JSONObject modules,Snapshot next,JSONArray history)throws Exception{if(!prefs(c).edit().putString("active",modules.toString()).putString("history",history.toString()).putInt("revision",prefs(c).getInt("revision",0)+1).remove("draft").commit())throw new IOException("No pude guardar la activación.");active=next;error="";}
 static synchronized String apply(Context c)throws Exception{String raw=prefs(c).getString("draft","");if(raw.isEmpty())return "No hay una sustitución pendiente.";JSONObject draft=new JSONObject(raw);if(draft.getInt("base")!=prefs(c).getInt("revision",0)||!draft.getString("priorHash").equals(JavaMethodEditor.hash(prefs(c).getString("active","{}")))||!draft.getString("workspaceHash").equals(workspace(c))||!workspace(c).equals(JavaProject.prefs(c).getString("compiledHash","")))throw new IOException("El candidato quedó desactualizado; preparalo otra vez.");JSONObject modules=draft.getJSONObject("modules");Snapshot next=load(c,modules,true);commit(c,modules,next,archive(c));return "Sustitución activa: "+draft.getString("kind")+". Funciona ahora sin instalar otro APK. Para volver: ‘deshace sustitucion java’.";}
 static synchronized String undo(Context c)throws Exception{JSONArray history=new JSONArray(prefs(c).getString("history","[]"));if(history.length()==0)return "No hay una sustitución anterior.";JSONObject previous=history.getJSONObject(history.length()-1);Snapshot next=load(c,previous,true);JSONArray remaining=new JSONArray();for(int i=0;i<history.length()-1;i++)remaining.put(history.getJSONObject(i));commit(c,previous,next,remaining);return "Recuperé las sustituciones anteriores. Las fuentes editadas siguen en la copia Java.";}
 static float value(Method m,float t,float fallback,float low,float high){if(m!=null)try{float v=((Number)m.invoke(null,Math.max(0,Math.min(1,t)))).floatValue();if(!Float.isNaN(v)&&!Float.isInfinite(v))return Math.max(low,Math.min(high,v));}catch(Throwable e){error="Falló una animación; usé el comportamiento anterior.";}return fallback;}
 static float jump(float t,float previous){return value(active.jump,t,previous,-40,0);}static float sway(float t,float previous){return value(active.sway,t,previous,-30,30);}
 static String reply(String message)throws Exception{return (String)active.chat.invoke(null,message);}
 static String recipe(String previous){if(active.celebration!=null)try{return (String)active.celebration.invoke(null);}catch(Throwable e){error="Falló la secuencia; usé la anterior.";}return previous;}
 static BananaEngine.Result handle(Context c,String input)throws Exception{String q=ChatLanguage.normalize(input);if(!q.matches("prepara sustitucion (animacion|chat|acciones|planificador)|aplica sustitucion java|deshace sustitucion java|desactiva sustituciones java|estado sustituciones java|ver sustitucion java|descarta sustitucion java|sustituciones java"))return null;try{String text;if(q.startsWith("prepara ")){JavaChat.owner=Thread.currentThread();try{text=prepare(c,q.substring("prepara sustitucion ".length()));}finally{JavaChat.owner=null;JavaChat.progress="";}}else if(q.startsWith("aplica "))text=apply(c);else if(q.startsWith("deshace "))text=undo(c);else if(q.startsWith("desactiva ")){commit(c,new JSONObject(),new Snapshot(),archive(c));text="Desactivé las sustituciones del proyecto. Podés deshacer esta operación.";}else if(q.startsWith("descarta ")){if(!prefs(c).edit().remove("draft").commit())throw new IOException("No pude descartar el candidato.");text="Descarté el candidato; las funciones activas siguen iguales.";}else if(q.startsWith("ver ")){String raw=prefs(c).getString("draft","");if(raw.isEmpty())text="Sin candidato pendiente. Activas:\n"+new JSONObject(prefs(c).getString("active","{}")).toString(2);else{JSONObject d=new JSONObject(raw);text="Candidato sin activar · "+d.getString("kind")+"\nMétodos que se conectarán:\n"+d.getJSONObject("modules").getJSONObject(d.getString("kind")).getJSONObject("spec").toString(2);}}else text="Sustituciones Java · revisión "+prefs(c).getInt("revision",0)+"\nActivas: "+(new JSONObject(prefs(c).getString("active","{}")).length()==0?"ninguna":new JSONObject(prefs(c).getString("active","{}")).names().toString())+"\n"+error+"\nEditá AnimationProfile.java#jump o #sway, ChatLanguage.java#socialReply , ActionProfile.java#celebration o PlannerProfile.java#rules.\nDespués: prepara sustitucion animacion / chat / acciones / planificador → ver sustitucion java → aplica sustitucion java.\nVolver: deshace sustitucion java.\nSe conectan cuatro funciones y el módulo de recetas del planificador. El resto del proyecto se compila sin ejecutarse.";return MobileCore.say(c,text,"app_ajuste");}catch(Exception e){return MobileCore.say(c,"No cambié las sustituciones activas: "+AndroidRepair.summary(e),"app_ajuste");}}
}
